#include <zephyr/ztest.h>
#include <zephyr/dfu/img_util.h> 
#include <zephyr/storage/flash_map.h>

#define SLOT0_PARTITION	slot0_partition
#define SLOT1_PARTITION	slot1_partition

#define SLOT0_ID		FIXED_PARTITION_ID(SLOT0_PARTITION)
#if FLASH_AREA_LABEL_EXISTS(slot1)
#define SLOT1_ID		FIXED_PARTITION_ID(SLOT1_PARTITION)
#endif

/* Test getting image information from flash_map */
ZTEST(img_util, test_img_info)
{
	uint8_t buf[16];
	size_t size;
	int ret;

	/* Check that we can get size of existing image */
	ret = img_util_get_image_size(SLOT0_ID, &size);
	zassert_ok(ret, "img_util_get_image_size failed");

	/* Check that we can read from existing image */
	ret = img_util_read(SLOT0_ID, 0, buf, sizeof(buf));
	zassert_ok(ret, "img_util_read failed");

#if FLASH_AREA_LABEL_EXISTS(slot1)
	/* Check that we can get size of existing image */
	ret = img_util_get_image_size(SLOT1_ID, &size);
	zassert_ok(ret, "img_util_get_image_size failed");

	/* Check that we can read from existing image */
	ret = img_util_read(SLOT1_ID, 0, buf, sizeof(buf));
	zassert_ok(ret, "img_util_read failed");
#endif
}

ZTEST_SUITE(img_util, NULL, NULL, NULL, NULL, NULL);
